import {
  CalendarRoot,
  CalendarNav,
  CalendarMonthView,
  CalendarWeekView,
  CalendarEventPopover,
  useCalendar,
  type CalendarEventBase,
} from "@/components/bevelui/calendar";

type MyEvent = CalendarEventBase & {
  projectId: string;
};

const events: MyEvent[] = [
  {
    id: "1",
    title: "Team standup",
    start: new Date(2025, 0, 13, 9, 0),
    end:   new Date(2025, 0, 13, 9, 30),
    color: "#60a5fa",
    projectId: "proj_abc",
  },
];

function Shell() {
  const { activeView } = useCalendar<MyEvent>();
  return (
    <>
      <CalendarNav />
      {activeView === "month" && <CalendarMonthView<MyEvent> />}
      {activeView === "week"  && <CalendarWeekView<MyEvent>  />}
      <CalendarEventPopover<MyEvent> />
    </>
  );
}

export function MyCalendar() {
  return (
    <CalendarRoot<MyEvent>
      events={events}
      config={{ defaultView: "week", weekStartsOn: 1 }}
      onRangeSelect={(start, end) => openCreateModal(start, end)}
      onEventMove={(event, newStart, newEnd) => updateEvent(event.id, newStart, newEnd)}
    >
      <Shell />
    </CalendarRoot>
  );
}

import type { CalendarEventBase } from "@/components/bevelui/calendar";

// Your domain model
type Task = CalendarEventBase & {
  assignee: string;
  priority: "low" | "medium" | "high";
  status: "todo" | "in-progress" | "done";
  projectId: string;
};

// The calendar is fully typed — renderEvent receives Task, not CalendarEventBase
<CalendarRoot<Task> events={tasks}>
  <CalendarWeekView<Task>
    renderEvent={(task, view) => (
      <TaskCard
        task={task}
        compact={view === "month"}
      />
    )}
  />
  <CalendarEventPopover<Task>
    renderEventPopover={(task, close) => (
      <TaskDetail task={task} onClose={close} />
    )}
  />
</CalendarRoot>

// Availability slots — only week view, working hours only, click-drag to book
<CalendarRoot<AvailabilitySlot>
  events={slots}
  config={{
    defaultView: "week",
    startHour: 8,
    endHour: 18,
    workingHours: { start: 9, end: 17 },
    snapToGrid: true,
    slotInterval: 30,
  }}
  onRangeSelect={(start, end) => openBookingForm({ start, end })}
>
  <Shell />
</CalendarRoot>

// Tasks by due date — month + agenda, sidebar mini nav, custom task cards
<CalendarRoot<Task> events={tasks}>
  <div className="flex h-screen">
    <aside className="w-52 p-4 border-r border-border">
      <CalendarMini />
    </aside>
    <div className="flex-1 flex flex-col p-4 gap-3">
      <CalendarNav views={["month", "agenda"]} />
      {activeView === "month"  && (
        <CalendarMonthView<Task>
          renderEvent={(task) => <TaskChip task={task} />}
        />
      )}
      {activeView === "agenda" && <CalendarAgendaView<Task> />}
    </div>
  </div>
  <CalendarEventPopover<Task>
    renderEventPopover={(task, close) => <TaskPanel task={task} />}
  />
</CalendarRoot>

// Staff shifts — week view, 6am–11pm, custom day headers with headcount
<CalendarRoot<Shift>
  events={shifts}
  config={{
    defaultView: "week",
    startHour: 6,
    endHour: 23,
    workingHours: null,  // no shading — every hour is fair game
  }}
  onEventMove={(shift, newStart, newEnd) =>
    updateShift(shift.id, { newStart, newEnd })
  }
>
  <CalendarNav views={["week", "day"]} />
  <CalendarWeekView<Shift>
    renderEvent={(shift) => <ShiftCard shift={shift} />}
    renderDayHeader={(date) => (
      <DayHeader date={date} staffCount={getStaffCount(date)} />
    )}
  />
  <CalendarEventPopover<Shift>
    renderEventPopover={(shift, close) => <ShiftDetail shift={shift} />}
  />
</CalendarRoot>
